#include <bits/stdc++.h>
using namespace std;

using ll = long long;

bool isPalindrome(ll x) {
    ll original = x, reversed = 0;
    while (x > 0) {
        reversed = reversed * 10 + x % 10;
        x /= 10;
    }
    return reversed == original;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    constexpr int LIMIT = 500000;
    ll p, q;
    cin >> p >> q;

    vector<bool> isPrime(LIMIT + 1, true);
    isPrime[0] = isPrime[1] = false;

    for (int i = 2; 1LL * i * i <= LIMIT; ++i) {
        if (isPrime[i]) {
            for (int j = i * i; j <= LIMIT; j += i)
                isPrime[j] = false;
        }
    }

    ll primeCount = 0, palindromeCount = 0, answer = 0;

    for (int i = 1; i <= LIMIT; ++i) {
        primeCount += isPrime[i];
        palindromeCount += isPalindrome(i);

        if (primeCount * q <= palindromeCount * p)
            answer = i;
    }

    if (answer == 0)
        cout << "Palindromic tree is better than splay tree";
    else
        cout << answer;

    return 0;
}

